"""Self-contained, contact-free manual research page; no third-party assets."""
PAGE = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Illoura research review</title><style>
:root{font:17px/1.5 system-ui,sans-serif;color:#153048;background:#edf2f6}*{box-sizing:border-box}body{margin:0}main{max-width:1040px;margin:auto;padding:24px}h1{margin:0}h2{font-size:1.25rem}p{max-width:75ch}header{background:#13364c;color:white;padding:28px}header>div{max-width:992px;margin:auto}.card{padding:24px;margin:20px 0;background:white;border:1px solid #c6d3dc;border-radius:12px;overflow-wrap:anywhere}label{display:block;font-weight:600;margin:14px 0 5px}input,textarea,select,button{font:inherit;max-width:100%;padding:10px;border:1px solid #73899a;border-radius:6px}input,textarea,select{width:100%;background:white;color:#153048}button{cursor:pointer;background:#fff;color:#153048;margin:6px 8px 6px 0;min-height:44px}button.primary{background:#11624e;color:white;border-color:#11624e}button.reject{color:#982d32;border-color:#982d32}button[aria-selected=true]{background:#153048;color:white}button:disabled{opacity:.55;cursor:wait}a{color:#075f96}small{font-size:.88rem}.warning{background:#fff0ce;padding:12px;border-radius:6px}.status{white-space:pre-wrap}nav{display:flex;flex-wrap:wrap;gap:4px}.hidden{display:none}dl{display:grid;grid-template-columns:minmax(100px,1fr) 3fr;gap:8px}dd{margin:0}dt{font-weight:600}:focus-visible{outline:3px solid #ce7d06;outline-offset:3px}@media(max-width:600px){main,header{padding:16px}.card{padding:16px}dl{display:block}dd{margin-bottom:12px}}
</style><header><div><h1>Research review</h1><p>Check the source, record your decision, and see when it is applied.</p></div></header><main>
<section class="card" id="access"><h2>Your review access</h2><p>Paste your personal review key. It stays in this browser tab’s session. Use “Forget key” when you finish on a shared device.</p><label for="key">Review key</label><input id="key" type="password" autocomplete="off" spellcheck="false"><button id="open" class="primary">Open review queue</button><button id="forget">Forget key</button></section>
<p id="message" role="status" aria-live="polite"></p><div id="work" class="hidden"><button id="refresh">Refresh queue and progress</button><p>Open the official evidence links before deciding. Skip anything you cannot confirm. Decisions are queued for checking; publication follows the next research snapshot.</p><nav role="tablist" aria-label="Review tasks"><button role="tab" data-tab="buyer" aria-selected="true">Buyer identities</button><button role="tab" data-tab="panel" aria-selected="false">Panels</button><button role="tab" data-tab="profile" aria-selected="false">Illoura profile</button></nav><div id="cards" role="tabpanel"></div><section class="card"><h2>Your decision progress</h2><p>Queued = waiting. Applied = recorded in the research database. Rejected = read the reason before trying again. An interrupted or uncertain application needs an owner’s audit check first.</p><div id="progress" aria-live="polite"></div></section></div>
<script>
'use strict';
let active='buyer', data={}, key=sessionStorage.getItem('illouraReviewKey')||'';
const el=id=>document.getElementById(id);el('key').value=key;
function node(tag,text,parent){let n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(parent)parent.append(n);return n;}
function field(parent,label,value,type='input'){let id='f'+(++field.count);node('label',label,parent).htmlFor=id;let n=node(type,undefined,parent);n.id=id;n.value=value??'';if(type==='textarea')n.maxLength=2000;else n.maxLength=2048;return n;}field.count=0;
function select(parent,label,choices,value){let n=field(parent,label,'','select');for(let [v,t] of choices){let o=node('option',t,n);o.value=v;}n.value=value;return n;}
function link(parent,url,text){try{let u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)return;}catch{return;}let a=node('a',text,parent);a.href=url;a.target='_blank';a.rel='noopener noreferrer';node('br','',parent);}
function button(parent,label,action,cls=''){let b=node('button',label,parent);b.className=cls;b.onclick=action;return b;}
async function api(path,body){let r=await fetch('/v1/review/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+key,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});let result=await r.json();if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:'The request could not be accepted. Refresh and check your entries.');return result;}
async function progress(){let p=await api('status');el('progress').replaceChildren();for(let d of p.decisions.slice().reverse()){node('p',d.kind+' · '+d.target+' · '+d.status+(d.reason?' — '+d.reason:'')+' · '+d.submitted_at+' · '+d.id,el('progress'));}if(!p.decisions.length)node('p','No decisions submitted with this key yet.',el('progress'));}
async function load(){try{data=await api('queue');await progress();el('work').classList.remove('hidden');el('message').textContent='Queue refreshed. Conflicts and changed identities appear first.';render();}catch(e){el('message').textContent=e.message;}}
function render(){el('cards').replaceChildren();let rows=data[active]||[];node('p',rows.length+' items in this snapshot',el('cards'));for(let r of rows){let c=node('article',undefined,el('cards'));c.className='card';let target=r.buyer_key||r.son_id||r.key;node('h2',r.buyer_name||r.panel_name||r.key.replaceAll('_',' '),c);let source=r.source_url||r.evidence_url||'', org=null;
if(active==='buyer'){node('p','Published ABN: '+(r.buyer_abn||'Unknown')+' · Match: '+r.match_status.replaceAll('_',' ')+' · '+r.review_status.replaceAll('_',' '),c);node('p','Match basis: '+r.evidence,c);if(r.register_context_stale||r.match_status==='conflict'){node('p',r.register_context_stale?'Register evidence has changed. Skip and ask the research owner to rebuild the queue.':'Sources disagree. Read every candidate source before deciding.',c).className='warning';}let choices=[['','Choose a government body']];let seen=new Set();for(let v of r.candidate_evidence||[]){node('p',v.name+' · ABN '+(v.abn||'Unknown')+' · '+v.source,c);link(c,v.source_url,'Open official register evidence');if(!seen.has(v.organisation_id)){choices.push([v.organisation_id,v.name]);seen.add(v.organisation_id);}if(!source&&v.source_url?.startsWith('https://'))source=v.source_url;}org=select(c,'Government body to approve',choices,r.organisation_id||'');}
if(active==='panel'){node('p','Owner: '+(r.owner_agency||'Unknown')+' · Notice expiry: '+(r.current_expiry||'Unknown')+' · Linked spend (12 months): '+(r.spend_through_panel_12m||'Unknown'),c);if(r.needs_manual_check)node('p','Needs a manual panel check. A relevance marking does not verify eligibility or joining rules.',c).className='warning';link(c,source,'Open panel source');}
if(active==='profile'){node('p','Current value: '+(r.value||'Not recorded'),c);node('p',r.note||'Use a verified Illoura fact.',c);link(c,source,'Open current evidence');}
let relevant,status,value;
if(active==='panel'){relevant=select(c,'Relevant to Illoura?', [['unknown','Unknown'],['yes','Yes'],['no','No']],r.marked_relevant===null?'unknown':r.marked_relevant?'yes':'no');status=select(c,'Illoura status',[['unknown','Unknown'],['member','Member'],['applied','Applied'],['not_applied','Not applied'],['not_eligible','Not eligible']],r.illoura_status);}
if(active==='profile'){value=field(c,'New fact value',r.value);value.maxLength=1000;}
let evidence=field(c,'HTTPS evidence link',source);evidence.type='url';let notes=field(c,'Note (optional, one line)',active==='panel'?r.notes:'');notes.maxLength=2000;let kind=active;
async function send(decision){try{let payload={kind,target,expected:r.expected,evidence_url:evidence.value,notes:notes.value};if(kind==='buyer'){payload.decision=decision;payload.organisation_id=decision==='approved'?org.value:null;}if(kind==='panel'){payload.relevant=relevant.value==='unknown'?null:relevant.value==='yes';payload.illoura_status=status.value;}if(kind==='profile')payload.value=value.value;for(let b of c.querySelectorAll('button'))b.disabled=true;let result=await api('decisions',payload);node('p','Queued: '+result.id+'. Check progress below before submitting again.',c);await progress();}catch(e){node('p',e.message,c).setAttribute('role','alert');for(let b of c.querySelectorAll('button'))b.disabled=false;}}
if(kind==='buyer'){button(c,'Approve',()=>send('approved'),'primary');button(c,'Reject',()=>send('rejected'),'reject');}else button(c,'Queue change',()=>send(),'primary');button(c,'Skip',()=>{c.remove();el('message').textContent='Skipped for this visit. Nothing has been changed.';});}}
el('open').onclick=()=>{key=el('key').value.trim();sessionStorage.setItem('illouraReviewKey',key);load();};el('forget').onclick=()=>{sessionStorage.removeItem('illouraReviewKey');key='';el('key').value='';el('work').classList.add('hidden');el('cards').replaceChildren();el('progress').replaceChildren();el('message').textContent='Key forgotten.';};el('refresh').onclick=load;for(let b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{active=b.dataset.tab;for(let t of document.querySelectorAll('[data-tab]'))t.setAttribute('aria-selected',String(t===b));render();};
</script></main></html>'''
